  "ai_overview": {
    "text_blocks": [
      {
        "type": "paragraph",
        "snippet": "You can check your Provident Fund (PF) balance using your Universal Account Number (UAN) through the EPFO Member Passbook Portal.",
        "snippet_links": [
          {
            "text": "EPFO Member Passbook Portal",
            "link": "https://passbook.epfindia.gov.in/"
          }
        ],
        "reference_indexes": [
          0,
          1
        ]
      },
      {
        "type": "heading",
        "snippet": "Via EPFO Passbook Website"
      },
      {
        "type": "list",
        "list": [
          {
            "snippet": "Go to the EPFO Member Passbook Portal."
          },
          {
            "snippet": "Enter your UAN and Password."
          },
          {
            "snippet": "Complete the captcha and click Login."
          },
          {
            "snippet": "Select your Member ID to view your balance and download your passbook.",
            "reference_indexes": [
              0,
              2,
              3,
              4
            ]
          }
        ]
      },
      {
        "type": "heading",
        "snippet": "Via UMANG App"
      },
      {
        "type": "list",
        "list": [
          {
            "snippet": "Open the UMANG App for EPFO.",
            "snippet_links": [
              {
                "text": "UMANG App for EPFO",
                "link": "https://web.umang.gov.in/landing/department/epfo.html"
              }
            ]
          },
          {
            "snippet": "Select Employee Centric Services and click on View Passbook."
          },
          {
            "snippet": "Enter your UAN."
          },
          {
            "snippet": "Type the OTP sent to your UAN-registered mobile number to see your balance.",
            "reference_indexes": [
              2,
              5,
              6,
              7
            ]
          }
        ]
      },
      {
        "type": "heading",
        "snippet": "Via Missed Call (Quick Method)"
      },
      {
        "type": "list",
        "list": [
          {
            "snippet": "Dial 9966044425 from your UAN-registered mobile number."
          },
          {
            "snippet": "The call will disconnect automatically and you will receive an SMS with your PF details."
          }
        ],
        "reference_indexes": [
          0,
          7,
          8
        ]
      },
      {
        "type": "heading",
        "snippet": "Via SMS"
      },
      {
        "type": "list",
        "list": [
          {
            "snippet": "Send an SMS in the format EPFOHO UAN to 7738299899 from your registered mobile number."
          }
        ],
        "reference_indexes": [
          0
        ]
      },
      {
        "type": "paragraph",
        "snippet": "If you want, let me know:"
      },
      {
        "type": "list",
        "list": [
          {
            "snippet": "Is your mobile number linked and active with your UAN?"
          },
          {
            "snippet": "Are you trying to check via mobile app or website?"
          }
        ]
      },
      {
        "type": "paragraph",
        "snippet": "I can give you more specific steps if you run into an error."
      }
    ],
